const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const N = 2000000;
function cpu(n) { let acc = 0; for (let i = 1; i <= n; i++) acc += i * i; return acc; }
if (isMainThread) {
  const mainResult = cpu(N);
  console.log('mainResult=' + mainResult);
  const w = new Worker(
    "const { parentPort, workerData } = require('worker_threads');" +
    "let acc = 0; for (let i = 1; i <= workerData.n; i++) acc += i * i;" +
    "parentPort.postMessage({ result: acc, thread: 'worker' });",
    { eval: true, workerData: { n: N } }
  );
  w.on('message', msg => {
    console.log('workerResult=' + msg.result);
    console.log('sameResult=' + (msg.result === mainResult));
    console.log('usedWorkerThread=' + (msg.thread === 'worker'));
  });
}
